const body = $input.item.json.body || $input.item.json;
const data = body.data || body;
const key = data.key || {};

// 1. Descartar se a mensagem foi enviada por mim mesmo
if (key.fromMe === true) {
  return [];
}

const rawJid = key.remoteJid || '';

// 2. BLOQUEIO DE GRUPOS: Não responder em grupos de WhatsApp
if (
  rawJid.includes('@g.us') || 
  rawJid.endsWith('@g.us') || 
  data.isGroup === true
) {
  return [];
}

// 3. BLOQUEIO DE LIGAÇÕES: Descartar eventos de chamada telefônica
const event = (body.event || data.event || '').toLowerCase();
const messageType = data.messageType || '';
if (
  event.includes('call') || 
  messageType === 'call' || 
  messageType === 'callLog' || 
  messageType === 'missedCallMessage' ||
  Boolean(data.call)
) {
  return [];
}

// Limpeza de sufixo multi-device (ex: 556294447055:0@s.whatsapp.net -> 556294447055@s.whatsapp.net)
const cleanJid = rawJid.replace(/:\d+@/, '@');
const isLid = cleanJid.includes('@lid') || cleanJid.endsWith('@lid');
const rawDigits = cleanJid.replace(/@.*$/, '').replace(/\D/g, '');

// Destino universal para resposta no WhatsApp:
// - Se conta @lid, usa o cleanJid diretamente (ex: 173456616341641@lid)
// - Se conta WhatsApp normal, usa os dígitos exatos da conta sem alterar nada (ex: 556294447055 ou 553298669536)
const number = isLid ? cleanJid : rawDigits;
const remoteJid = cleanJid;

if (!number || number.length < 5) {
  return [];
}

// 4. TRAVA ATÔMICA DE IDEMPOTÊNCIA ANTI-DUPLICAÇÃO (PRIMARY KEY msgId):
// Evita que webhooks repetidos do WhatsApp/Baileys façam o Marcão responder 2 ou 3 vezes ao mesmo áudio/texto!
const supabaseUrl = "https://qkopgftfrfftoyndhhfj.supabase.co";
const supabaseKey = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFrb3BnZnRmcmZmdG95bmRoaGZqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MTgwMTU4MywiZXhwIjoyMTA3Mzc3NTgzfQ.S_RRdnI6SZTVR1UH7jryDVHf316YmnMOVEBuoedyKv8";

const incomingMsgId = key.id || '';
if (incomingMsgId) {
  try {
    // Tenta registrar o msgId no banco (user_id é Primary Key única!)
    // Se já existir, o Supabase rejeita com 409 Conflict instantaneamente!
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${supabaseUrl}/rest/v1/n8n_controle_pausa`,
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        user_id: incomingMsgId,
        telefone: number,
        pausado_ate: new Date(Date.now() + 86400000).toISOString()
      },
      json: true
    });
  } catch (err) {
    // Se der erro 409 ou duplicidade, significa que outra execução já pegou esta mensagem!
    // Descarta imediatamente sem responder de novo!
    return [];
  }
}

// 5. RECONHECIMENTO ESTRITO DO DIRETOR EVANDRO GALLINA:
// REGRA MANDATÓRIA DO USUÁRIO:
// Apenas e exclusivamente o número pessoal 32984587255 (ou o LID pessoal 179009992298658) é o CHEFE.
// Qualquer outro número de WhatsApp é CLIENTE normal, mesmo que o nome do perfil seja "Evandro", "Evandro Silva Gallina", etc.
const isEvandro = (
  rawDigits === '5532984587255' ||
  rawDigits === '553284587255' ||
  rawDigits.endsWith('32984587255') ||
  rawDigits.endsWith('3284587255') ||
  cleanJid.includes('179009992298658')
);

// Desempacotamento de mensagens temporárias (ephemeral) e de visualização única (viewOnce)
let msg = data.message || {};
while (
  msg.ephemeralMessage ||
  msg.viewOnceMessage ||
  msg.viewOnceMessageV2 ||
  msg.viewOnceMessageV2Extension ||
  msg.documentWithCaptionMessage
) {
  msg = (
    msg.ephemeralMessage?.message ||
    msg.viewOnceMessage?.message ||
    msg.viewOnceMessageV2?.message ||
    msg.viewOnceMessageV2Extension?.message ||
    msg.documentWithCaptionMessage?.message ||
    msg
  );
}

// Desempacotamento de contatos (contactMessage ou contactsArrayMessage)
let contatoCompartilhado = null;
if (msg.contactMessage || messageType === 'contactMessage') {
  const cm = msg.contactMessage || {};
  const vcard = cm.vcard || '';
  const waidMatch = vcard.match(/waid=(\d+)/);
  const telMatch = vcard.match(/TEL[^:]*:(.*)/);
  let phone = waidMatch ? waidMatch[1] : (telMatch ? telMatch[1].replace(/\D/g, '') : '');
  let contactName = cm.displayName || '';
  if (!contactName) {
    const fnMatch = vcard.match(/FN:(.*)/);
    if (fnMatch) contactName = fnMatch[1].trim();
  }
  if (phone && !phone.startsWith('55') && phone.length <= 11) {
    phone = '55' + phone;
  }
  contatoCompartilhado = { nome: contactName || 'Contato', numero: phone };
} else if (msg.contactsArrayMessage || messageType === 'contactsArrayMessage') {
  const contacts = msg.contactsArrayMessage?.contacts || [];
  if (contacts.length > 0) {
    const cm = contacts[0];
    const vcard = cm.vcard || '';
    const waidMatch = vcard.match(/waid=(\d+)/);
    const telMatch = vcard.match(/TEL[^:]*:(.*)/);
    let phone = waidMatch ? waidMatch[1] : (telMatch ? telMatch[1].replace(/\D/g, '') : '');
    let contactName = cm.displayName || '';
    if (phone && !phone.startsWith('55') && phone.length <= 11) {
      phone = '55' + phone;
    }
    contatoCompartilhado = { nome: contactName || 'Contato', numero: phone };
  }
}

const isAudio = Boolean(msg.audioMessage || messageType === 'audioMessage');
const isFoto = Boolean(msg.imageMessage || messageType === 'imageMessage');
const isPdf = Boolean(msg.documentMessage || messageType === 'documentMessage');

let texto = (
  msg.conversation || 
  msg.extendedTextMessage?.text || 
  msg.imageMessage?.caption || 
  msg.videoMessage?.caption || 
  msg.documentMessage?.caption ||
  ''
).trim();

if (!texto) {
  if (isAudio) {
    texto = '[Mensagem de áudio recebida]';
  } else if (isFoto) {
    if (isEvandro) {
      texto = '[O Diretor Evandro enviou foto(s)/arte(s) do Marcão]';
    } else {
      texto = '[O cliente enviou uma imagem/foto sem legenda]';
    }
  } else if (isPdf) {
    texto = '[Documento/Exame em PDF enviado]';
  } else {
    const tecnicos = ['reactionMessage', 'protocolMessage', 'senderKeyDistributionMessage', 'messageContextInfo', 'editedMessage', 'pollUpdateMessage', 'keepInChatMessage'];
    const chaves = Object.keys(msg).filter(k => !tecnicos.includes(k));
    const tipo = chaves[0] || messageType || '';
    if (!tipo) {
      return [];
    }
    if (tipo === 'stickerMessage') texto = '[O cliente enviou uma figurinha]';
    else if (tipo === 'videoMessage') texto = '[O cliente enviou um vídeo]';
    else if (tipo === 'locationMessage' || tipo === 'liveLocationMessage') texto = '[O cliente enviou uma localização]';
    else if (tipo === 'contactMessage' || tipo === 'contactsArrayMessage' || contatoCompartilhado) {
      if (contatoCompartilhado && contatoCompartilhado.numero) {
        texto = `[Contato compartilhado: ${contatoCompartilhado.nome} (WhatsApp: ${contatoCompartilhado.numero})]`;
      } else {
        texto = '[O cliente enviou um contato]';
      }
    }
    else if (tipo === 'placeholderMessage' || tipo === 'templateMessage') texto = '[Mensagem não carregou no WhatsApp; peça com simpatia para o cliente reenviar]';
    else texto = '[O cliente enviou uma mensagem do tipo ' + tipo + ']';
  }
}

const msgId = incomingMsgId || ('msg_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7));

function sanitizarNome(n) {
  if (!n) return '';
  return n.trim().replace(/[\r\n\t;\"<>\\]/g, '').slice(0, 50).trim();
}

let pushName = sanitizarNome(data.pushName || '');
const matchNome = texto.match(/(?:meu nome é|me chamo|pode me chamar de|sou o|sou a)\s+([A-Za-zÀ-ÿ\' ]+)/i);
if (matchNome && matchNome[1]) {
  const nomeCapturado = sanitizarNome(matchNome[1].split(' ')[0]);
  if (nomeCapturado.length >= 2) {
    pushName = nomeCapturado;
  }
}

const nomeValido = (
  Boolean(pushName) && 
  pushName.length >= 2 && 
  !pushName.replace('+', '').match(/^\d+$/) && 
  !pushName.match(/^[\.\-_,~!@#$%^&*()]+$/)
);

let primeiroNome = '';
if (isEvandro) {
  primeiroNome = 'Evandro';
} else if (nomeValido) {
  primeiroNome = pushName.split(' ')[0];
}

let genero = 'homem';
if (primeiroNome) {
  const pLower = primeiroNome.toLowerCase();
  const excecoesMasc = ['lucas', 'joshua', 'elias', 'luca', 'isaac', 'jean', 'alan', 'alex', 'nicolas'];
  const excecoesFem = ['beatriz', 'ingrid', 'karen', 'carmen', 'miriam', 'ruth', 'ester', 'raquel', 'elis', 'iris'];
  if (excecoesMasc.includes(pLower)) {
    genero = 'homem';
  } else if (excecoesFem.includes(pLower)) {
    genero = 'mulher';
  } else if (pLower.endsWith('a') || (pLower.endsWith('e') && ['julie', 'stephanie', 'simone', 'monique'].includes(pLower))) {
    genero = 'mulher';
  }
}

let emojiReacao = '👊';
if (isFoto || isPdf) {
  emojiReacao = '🔥';
} else if (isAudio) {
  emojiReacao = '👂';
} else if (isEvandro || (texto && texto.toLowerCase().includes('treino'))) {
  emojiReacao = '💪';
} else if (texto && /obrigad|valeu|show|top|sensacional|maravilha|obg/i.test(texto)) {
  emojiReacao = '🚀';
} else if (texto && /^(ok|blz|beleza|combinado|fechado|sim|tá|ta)[\.!\s]*$/i.test(texto.trim())) {
  emojiReacao = '👍';
}

return [{
  json: {
    emojiReacao: emojiReacao,
    msgId: msgId,
    remoteJid: remoteJid,
    number: number,
    pushName: pushName,
    nomeValido: nomeValido,
    primeiroNome: primeiroNome,
    isEvandro: isEvandro,
    isLid: isLid,
    genero: genero,
    textoRecebido: texto,
    isAudio: isAudio,
    isFoto: isFoto,
    isPdf: isPdf,
    contatoCompartilhado: contatoCompartilhado,
    rawMessageData: data,
    timestamp: Math.floor(Date.now() / 1000)
  }
}];

const norm = $('Normalizar Contato & Detecção de Mídia').item.json;
const items = $input.all();

if (!items || items.length === 0) {
  return [];
}

const latestItem = items[items.length - 1].json;
if (latestItem.id_mensagem !== norm.msgId) {
  return [];
}

const msgs = items.map(it => it.json.mensagem).filter(Boolean);
let textoConsolidado = '';
const isEvandro = norm.isEvandro;

const countFotosEvandro = msgs.filter(m => m.includes('arte(s) do Marcão') || m.includes('foto(s)')).length;
const countFotosCliente = msgs.filter(m => m.includes('imagem/foto sem legenda')).length;

if (isEvandro && countFotosEvandro > 1) {
  textoConsolidado = `[O Diretor Evandro enviou ${countFotosEvandro} fotos/artes do Marcão]`;
} else if (!isEvandro && countFotosCliente > 1) {
  textoConsolidado = `[O cliente enviou ${countFotosCliente} fotos/imagens sem legenda]`;
} else if (msgs.length > 1) {
  textoConsolidado = msgs.join('\n');
} else {
  textoConsolidado = msgs[0] || norm.textoRecebido;
}

const textoLower = textoConsolidado.toLowerCase();

const gatilhosHumano = [
  'falar com humano', 'falar com um humano', 'falar com pessoa', 'falar com uma pessoa',
  'atendente humano', 'falar com atendente', 'passa para atendente', 'passa pro atendente',
  'falar com alguém', 'falar com alguem', 'falar com evandro', 'falar com o evandro',
  'atendimento humano', 'pessoa de verdade', 'falar com o dono', 'falar com suporte humano'
];
const pedeHumano = !isEvandro && gatilhosHumano.some(g => textoLower.includes(g));
const isAprovacaoRui = isEvandro && (
  textoLower.includes('aprovar rui') || 
  textoLower.trim() === 'aprovar' || 
  textoLower.includes('aprova rui') ||
  textoLower.includes('aprovar campanha')
);

// Deteccao refinada de instrucao de orcamento do Diretor Evandro
let isAjusteOrcamentoRui = false;
let novoValorDiario = null;
let diasDuracao = 1;

if (isEvandro && !isAprovacaoRui) {
  const temPalavraChaveOrcamento = /(?:bota|coloca|aumenta|orcamento|orçamento|investir|gasta|gastar|subir|sobe|diminuir)\s*(?:o\s*orçamento\s*)?(?:para\s*|de\s*|em\s*)?(?:r\$\s*)?(\d+(?:[.,]\d{1,2})?)/i.test(textoLower) ||
                                  /(\d+(?:[.,]\d{1,2})?)\s*(?:reais|conto)\s*(?:por dia|\/dia|durante|por|\s)/i.test(textoLower);

  if (temPalavraChaveOrcamento && (textoLower.includes('campanha') || textoLower.includes('rui') || textoLower.includes('trafego') || textoLower.includes('tráfego') || textoLower.includes('anuncio') || textoLower.includes('anúncio') || textoLower.includes('reais') || textoLower.includes('dia') || textoLower.includes('marcão') || textoLower.includes('marcao') || textoLower.includes('orçamento') || textoLower.includes('orcamento') || textoLower.includes('sobe') || textoLower.includes('aumenta') || textoLower.includes('bota'))) {
    const valMatch = textoLower.match(/(?:bota|coloca|aumenta|orcamento|orçamento|investir|gasta|gastar|subir|sobe|diminuir|para|de)\s*(?:o\s*orçamento\s*)?(?:para\s*|de\s*|em\s*)?(?:r\$\s*)?(\d+(?:[.,]\d{1,2})?)/i) ||
                     textoLower.match(/(\d+(?:[.,]\d{1,2})?)\s*(?:reais|conto)/i);
    if (valMatch) {
      novoValorDiario = parseFloat(valMatch[1].replace(',', '.'));
      const diaMatch = textoLower.match(/(?:por|durante|em|prazo de)\s*(\d+)\s*dias?/i) || textoLower.match(/(\d+)\s*dias?/i);
      if (diaMatch) {
        diasDuracao = parseInt(diaMatch[1], 10);
      }
      isAjusteOrcamentoRui = true;
    }
  }
}

const isComandoRui = isAprovacaoRui || isAjusteOrcamentoRui;

const pediuAudio = (
  norm.isAudio ||
  textoLower.includes('mande um áudio') ||
  textoLower.includes('mande um audio') ||
  textoLower.includes('manda um áudio') ||
  textoLower.includes('manda um audio') ||
  textoLower.includes('mandei um áudio') ||
  textoLower.includes('mandei um audio') ||
  textoLower.includes('manda audio') ||
  textoLower.includes('manda áudio') ||
  textoLower.includes('grava um áudio') ||
  textoLower.includes('grava um audio') ||
  textoLower.includes('audio seu') ||
  textoLower.includes('áudio seu')
);

const temMidia = Boolean(norm.isFoto || norm.isPdf);

return [{
  json: {
    ...norm,
    textoRecebido: textoConsolidado,
    pedeHumano: pedeHumano,
    pediuAudio: pediuAudio,
    temMidia: temMidia,
    isAprovacaoRui: isAprovacaoRui,
    isAjusteOrcamentoRui: isAjusteOrcamentoRui,
    novoValorDiario: novoValorDiario,
    diasDuracao: diasDuracao,
    isComandoRui: isComandoRui
  }
}];

