parameters.jsCode:
const evoMedia = $input.first() ? $input.first().json : {};
const prev = $('Consolidar Mensagens e Filtrar Vencedor').item.json;

let mediaBase64 = null;
let mediaMimetype = null;
let isFotoReal = false;
let isPdfReal = false;

if (evoMedia && evoMedia.base64) {
  mediaBase64 = evoMedia.base64;
  mediaMimetype = evoMedia.mimetype || 'image/jpeg';
  if (mediaMimetype.startsWith('image/')) {
    isFotoReal = true;
  } else if (mediaMimetype.includes('pdf')) {
    isPdfReal = true;
  }
}

return [{
  json: {
    ...prev,
    mediaBase64: mediaBase64,
    mediaMimetype: mediaMimetype,
    isFotoReal: isFotoReal,
    isPdfReal: isPdfReal,
    fileName: evoMedia.fileName || ''
  }
}];

const prev = $input.first() ? $input.first().json : {};
const remoteJid = prev.remoteJid || '';
const number = prev.number || '';
const userText = (prev.text || prev.body || prev.mensagem || '').trim();
const txtLow = userText.toLowerCase();

const supabaseUrl = "https://qkopgftfrfftoyndhhfj.supabase.co";
const supabaseKey = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFrb3BnZnRmcmZmdG95bmRoaGZqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MTgwMTU4MywiZXhwIjoyMTA3Mzc3NTgzfQ.S_RRdnI6SZTVR1UH7jryDVHf316YmnMOVEBuoedyKv8";

// 1. Buscar histórico de conversas
let histData = [];
try {
  let url = `${supabaseUrl}/rest/v1/leads_conversas?select=historico_mensagens,etapa_funil,push_name`;
  if (remoteJid && number) {
    url += `&or=(remote_jid.eq.${encodeURIComponent(remoteJid)},telefone.eq.${encodeURIComponent(number)})`;
  } else if (remoteJid) {
    url += `&remote_jid=eq.${encodeURIComponent(remoteJid)}`;
  } else if (number) {
    url += `&telefone=eq.${encodeURIComponent(number)}`;
  }

  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` },
    json: true
  });
  if (Array.isArray(res)) histData = res;
} catch (e) {}

// 2. Buscar Ficha Clínica do Aluno
let fichaAluno = null;
const cleanNum = number.replace(/\D/g, '');
const last8 = cleanNum.slice(-8);

try {
  const rFicha = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/fichas_alunos?select=*`,
    headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` },
    json: true
  });
  if (Array.isArray(rFicha)) {
    fichaAluno = rFicha.find(f => {
      const fNum = (f.telefone || '').replace(/\D/g, '');
      const fJid = (f.remote_jid || '').replace(/\D/g, '');
      return (last8 && (fNum.endsWith(last8) || fJid.includes(last8))) || (remoteJid && f.remote_jid === remoteJid);
    });
  }
} catch (e) {}

// 3. Processamento de LGPD ('CONCORDO') e Parser Clínico
const patchFicha = {};
const agoraIso = new Date().toISOString();

// A. Detecção de 'CONCORDO' / Consentimento LGPD
const termosConcordo = ["concordo", "ciente", "autorizo", "aceito", "sim", "com certeza", "pode", "ok", "claro", "bora", "fechado"];
const ehConcordo = termosConcordo.some(t => txtLow.includes(t)) || prev.isEvandro;

if (ehConcordo && (!fichaAluno || !fichaAluno.consentimento_lgpd)) {
  patchFicha.consentimento_lgpd = true;
  patchFicha.data_consentimento_lgpd = agoraIso;
  patchFicha.termo_lgpd_versao = 'v2.0_lgpd';
  patchFicha.status_acompanhamento = 'ativo';
}

// B. Extração de Idade
const matchIdade = txtLow.match(/\b(?:tenho|minha idade [eé]|idade[:\s]*)?(\d{1,2})\s*(?:anos|ano)?\b/);
if (matchIdade) {
  const idVal = parseInt(matchIdade[1], 10);
  if (idVal >= 12 && idVal <= 95) patchFicha.idade = idVal;
}

// C. Extração de Peso
const matchPeso = txtLow.match(/\b(?:peso|pesando|estou com|to com|de)?\s*(\d{2,3}(?:[.,]\d{1,2})?)\s*(?:kg|quilos|kilos)\b/) ||
                  txtLow.match(/\bpeso[:\s]*(\d{2,3}(?:[.,]\d{1,2})?)\b/);
if (matchPeso) {
  const pVal = parseFloat(matchPeso[1].replace(',', '.'));
  if (pVal >= 35 && pVal <= 250) {
    patchFicha.metas_nutricionais = {
      ...(fichaAluno?.metas_nutricionais || {}),
      peso: pVal
    };
  }
}

// D. Extração de Altura
const matchAltura = txtLow.match(/\b(?:altura[:\s]*)?(1[.,]\d{2})\s*(?:m|metros)?\b/) ||
                    txtLow.match(/\b(?:altura[:\s]*)?(1\d{2})\s*(?:cm)?\b/);
if (matchAltura) {
  let altCm = parseFloat(matchAltura[1].replace(',', '.'));
  if (altCm < 3) altCm = Math.round(altCm * 100);
  if (altCm >= 120 && altCm <= 230) {
    patchFicha.metas_nutricionais = {
      ...(patchFicha.metas_nutricionais || fichaAluno?.metas_nutricionais || {}),
      altura_cm: altCm
    };
  }
}

// E. Local de Treino
