const body = $input.item.json.body || $input.item.json;
const data = body.data || body;
const key = data.key || {};

// 1. Descartar se a mensagem foi enviada por mim mesmo
if (key.fromMe === true) {
  return [];
}

const rawJid = key.remoteJid || '';

// 2. BLOQUEIO DE GRUPOS: Não responder em grupos de WhatsApp
if (
  rawJid.includes('@g.us') || 
  rawJid.endsWith('@g.us') || 
  data.isGroup === true
) {
  return [];
}

// 3. BLOQUEIO DE LIGAÇÕES: Descartar eventos de chamada telefônica
const event = (body.event || data.event || '').toLowerCase();
const messageType = data.messageType || '';
if (
  event.includes('call') || 
  messageType === 'call' || 
  messageType === 'callLog' || 
  messageType === 'missedCallMessage' ||
  Boolean(data.call)
) {
  return [];
}

// Limpeza de sufixo multi-device (ex: 556294447055:0@s.whatsapp.net -> 556294447055@s.whatsapp.net)
const cleanJid = rawJid.replace(/:\d+@/, '@');
const isLid = cleanJid.includes('@lid') || cleanJid.endsWith('@lid');
const rawDigits = cleanJid.replace(/@.*$/, '').replace(/\D/g, '');

// Destino universal para resposta no WhatsApp:
// - Se conta @lid, usa o cleanJid diretamente (ex: 173456616341641@lid)
// - Se conta WhatsApp normal, usa os dígitos exatos da conta sem alterar nada (ex: 556294447055 ou 553298669536)
const number = isLid ? cleanJid : rawDigits;
const remoteJid = cleanJid;

if (!number || number.length < 5) {
  return [];
}

// 4. TRAVA ATÔMICA DE IDEMPOTÊNCIA ANTI-DUPLICAÇÃO (PRIMARY KEY msgId):
// Evita que webhooks repetidos do WhatsApp/Baileys façam o Marcão responder 2 ou 3 vezes ao mesmo áudio/texto!
const supabaseUrl = "https://qkopgftfrfftoyndhhfj.supabase.co";
const supabaseKey = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFrb3BnZnRmcmZmdG95bmRoaGZqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MTgwMTU4MywiZXhwIjoyMTA3Mzc3NTgzfQ.S_RRdnI6SZTVR1UH7jryDVHf316YmnMOVEBuoedyKv8";

const incomingMsgId = key.id || '';
if (incomingMsgId) {
  try {
    // Tenta registrar o msgId no banco (user_id é Primary Key única!)
    // Se já existir, o Supabase rejeita com 409 Conflict instantaneamente!
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${supabaseUrl}/rest/v1/n8n_controle_pausa`,
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        user_id: incomingMsgId,
        telefone: number,
        pausado_ate: new Date(Date.now() + 86400000).toISOString()
      },
      json: true
    });
  } catch (err) {
    // Se der erro 409 ou duplicidade, significa que outra execução já pegou esta mensagem!
    // Descarta imediatamente sem responder de novo!
    return [];
  }
}

// 5. RECONHECIMENTO ESTRITO DO DIRETOR EVANDRO GALLINA:
// REGRA MANDATÓRIA DO USUÁRIO:
// Apenas e exclusivamente o número pessoal 32984587255 (ou o LID pessoal 179009992298658) é o CHEFE.
// Qualquer outro número de WhatsApp é CLIENTE normal, mesmo que o nome do perfil seja "Evandro", "Evandro Silva Gallina", etc.
const isEvandro = (
  rawDigits === '5532984587255' ||
  rawDigits === '553284587255' ||
  rawDigits.endsWith('32984587255') ||
  rawDigits.endsWith('3284587255') ||
  cleanJid.includes('179009992298658')
);

// Desempacotamento de mensagens temporárias (ephemeral) e de visualização única (viewOnce)
let msg = data.message || {};
while (
  msg.ephemeralMessage ||
  msg.viewOnceMessage ||
  msg.viewOnceMessageV2 ||
  msg.viewOnceMessageV2Extension ||
  msg.documentWithCaptionMessage
) {
  msg = (
    msg.ephemeralMessage?.message ||
    msg.viewOnceMessage?.message ||
    msg.viewOnceMessageV2?.message ||
    msg.viewOnceMessageV2Extension?.message ||
    msg.documentWithCaptionMessage?.message ||
    msg
  );
}

// Desempacotamento de contatos (contactMessage ou contactsArrayMessage)
let contatoCompartilhado = null;
if (msg.contactMessage || messageType === 'contactMessage') {
  const cm = msg.contactMessage || {};
  const vcard = cm.vcard || '';
  const waidMatch = vcard.match(/waid=(\d+)/);
  const telMatch = vcard.match(/TEL[^:]*:(.*)/);
  let phone = waidMatch ? waidMatch[1] : (telMatch ? telMatch[1].replace(/\D/g, '') : '');
  let contactName = cm.displayName || '';
  if (!contactName) {
    const fnMatch = vcard.match(/FN:(.*)/);
