}

const isAudio = Boolean(msg.audioMessage || messageType === 'audioMessage');
const isFoto = Boolean(msg.imageMessage || messageType === 'imageMessage');
const isPdf = Boolean(msg.documentMessage || messageType === 'documentMessage');

let texto = (
  msg.conversation || 
