  } else if (isPdf) {
    texto = '[Documento/Exame em PDF enviado]';
  } else {
    const tecnicos = ['reactionMessage', 'protocolMessage', 'senderKeyDistributionMessage', 'messageContextInfo', 'editedMessage', 'pollUpdateMessage', 'keepInChatMessage'];
    const chaves = Object.keys(msg).filter(k => !tecnicos.includes(k));
    const tipo = chaves[0] || messageType || '';
    if (!tipo) {
      return [];
    }
    if (tipo === 'stickerMessage') texto = '[O cliente enviou uma figurinha]';
    else if (tipo === 'videoMessage') texto = '[O cliente enviou um vídeo]';
    else if (tipo === 'locationMessage' || tipo === 'liveLocationMessage') texto = '[O cliente enviou uma localização]';
    else if (tipo === 'contactMessage' || tipo === 'contactsArrayMessage' || contatoCompartilhado) {
      if (contatoCompartilhado && contatoCompartilhado.numero) {
        texto = `[Contato compartilhado: ${contatoCompartilhado.nome} (WhatsApp: ${contatoCompartilhado.numero})]`;
      } else {
        texto = '[O cliente enviou um contato]';
      }
    }
    else if (tipo === 'placeholderMessage' || tipo === 'templateMessage') texto = '[Mensagem não carregou no WhatsApp; peça com simpatia para o cliente reenviar]';
    else texto = '[O cliente enviou uma mensagem do tipo ' + tipo + ']';
  }
}

const msgId = incomingMsgId || ('msg_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7));

function sanitizarNome(n) {
  if (!n) return '';
  return n.trim().replace(/[\r\n\t;\"<>\\]/g, '').slice(0, 50).trim();
}

let pushName = sanitizarNome(data.pushName || '');
const matchNome = texto.match(/(?:meu nome é|me chamo|pode me chamar de|sou o|sou a)\s+([A-Za-zÀ-ÿ\' ]+)/i);
if (matchNome && matchNome[1]) {
  const nomeCapturado = sanitizarNome(matchNome[1].split(' ')[0]);
  if (nomeCapturado.length >= 2) {
    pushName = nomeCapturado;
  }
}

const nomeValido = (
  Boolean(pushName) && 
  pushName.length >= 2 && 
  !pushName.replace('+', '').match(/^\d+$/) && 
  !pushName.match(/^[\.\-_,~!@#$%^&*()]+$/)
);

let primeiroNome = '';
if (isEvandro) {
  primeiroNome = 'Evandro';
} else if (nomeValido) {
  primeiroNome = pushName.split(' ')[0];
}

let genero = 'homem';
if (primeiroNome) {
  const pLower = primeiroNome.toLowerCase();
  const excecoesMasc = ['lucas', 'joshua', 'elias', 'luca', 'isaac', 'jean', 'alan', 'alex', 'nicolas'];
  const excecoesFem = ['beatriz', 'ingrid', 'karen', 'carmen', 'miriam', 'ruth', 'ester', 'raquel', 'elis', 'iris'];
  if (excecoesMasc.includes(pLower)) {
    genero = 'homem';
  } else if (excecoesFem.includes(pLower)) {
    genero = 'mulher';
  } else if (pLower.endsWith('a') || (pLower.endsWith('e') && ['julie', 'stephanie', 'simone', 'monique'].includes(pLower))) {
    genero = 'mulher';
  }
}

let emojiReacao = '👊';
if (isFoto || isPdf) {
  emojiReacao = '🔥';
} else if (isAudio) {
  emojiReacao = '👂';
} else if (isEvandro || (texto && texto.toLowerCase().includes('treino'))) {
  emojiReacao = '💪';
} else if (texto && /obrigad|valeu|show|top|sensacional|maravilha|obg/i.test(texto)) {
  emojiReacao = '🚀';
} else if (texto && /^(ok|blz|beleza|combinado|fechado|sim|tá|ta)[\.!\s]*$/i.test(texto.trim())) {
  emojiReacao = '👍';
}

return [{
  json: {
    emojiReacao: emojiReacao,
    msgId: msgId,
    remoteJid: remoteJid,
    number: number,
    pushName: pushName,
    nomeValido: nomeValido,
    primeiroNome: primeiroNome,
    isEvandro: isEvandro,
    isLid: isLid,
    genero: genero,
    textoRecebido: texto,
    isAudio: isAudio,
    isFoto: isFoto,
    isPdf: isPdf,
    contatoCompartilhado: contatoCompartilhado,
    rawMessageData: data,
    timestamp: Math.floor(Date.now() / 1000)
  }
}];

const norm = $('Normalizar Contato & Detecção de Mídia').item.json;
const items = $input.all();

if (!items || items.length === 0) {
  return [];
}

const latestItem = items[items.length - 1].json;
if (latestItem.id_mensagem !== norm.msgId) {
  return [];
}

const msgs = items.map(it => it.json.mensagem).filter(Boolean);
let textoConsolidado = '';
const isEvandro = norm.isEvandro;

const countFotosEvandro = msgs.filter(m => m.includes('arte(s) do Marcão') || m.includes('foto(s)')).length;
const countFotosCliente = msgs.filter(m => m.includes('imagem/foto sem legenda')).length;

if (isEvandro && countFotosEvandro > 1) {
