} else if (msgs.length > 1) {
  textoConsolidado = msgs.join('\n');
} else {
  textoConsolidado = msgs[0] || norm.textoRecebido;
}

const textoLower = textoConsolidado.toLowerCase();

const gatilhosHumano = [
  'falar com humano', 'falar com um humano', 'falar com pessoa', 'falar com uma pessoa',
  'atendente humano', 'falar com atendente', 'passa para atendente', 'passa pro atendente',
  'falar com alguém', 'falar com alguem', 'falar com evandro', 'falar com o evandro',
  'atendimento humano', 'pessoa de verdade', 'falar com o dono', 'falar com suporte humano'
];
const pedeHumano = !isEvandro && gatilhosHumano.some(g => textoLower.includes(g));
const isAprovacaoRui = isEvandro && (
  textoLower.includes('aprovar rui') || 
  textoLower.trim() === 'aprovar' || 
  textoLower.includes('aprova rui') ||
  textoLower.includes('aprovar campanha')
);

// Deteccao refinada de instrucao de orcamento do Diretor Evandro
let isAjusteOrcamentoRui = false;
let novoValorDiario = null;
let diasDuracao = 1;

if (isEvandro && !isAprovacaoRui) {
  const temPalavraChaveOrcamento = /(?:bota|coloca|aumenta|orcamento|orçamento|investir|gasta|gastar|subir|sobe|diminuir)\s*(?:o\s*orçamento\s*)?(?:para\s*|de\s*|em\s*)?(?:r\$\s*)?(\d+(?:[.,]\d{1,2})?)/i.test(textoLower) ||
                                  /(\d+(?:[.,]\d{1,2})?)\s*(?:reais|conto)\s*(?:por dia|\/dia|durante|por|\s)/i.test(textoLower);

  if (temPalavraChaveOrcamento && (textoLower.includes('campanha') || textoLower.includes('rui') || textoLower.includes('trafego') || textoLower.includes('tráfego') || textoLower.includes('anuncio') || textoLower.includes('anúncio') || textoLower.includes('reais') || textoLower.includes('dia') || textoLower.includes('marcão') || textoLower.includes('marcao') || textoLower.includes('orçamento') || textoLower.includes('orcamento') || textoLower.includes('sobe') || textoLower.includes('aumenta') || textoLower.includes('bota'))) {
    const valMatch = textoLower.match(/(?:bota|coloca|aumenta|orcamento|orçamento|investir|gasta|gastar|subir|sobe|diminuir|para|de)\s*(?:o\s*orçamento\s*)?(?:para\s*|de\s*|em\s*)?(?:r\$\s*)?(\d+(?:[.,]\d{1,2})?)/i) ||
                     textoLower.match(/(\d+(?:[.,]\d{1,2})?)\s*(?:reais|conto)/i);
    if (valMatch) {
      novoValorDiario = parseFloat(valMatch[1].replace(',', '.'));
      const diaMatch = textoLower.match(/(?:por|durante|em|prazo de)\s*(\d+)\s*dias?/i) || textoLower.match(/(\d+)\s*dias?/i);
      if (diaMatch) {
        diasDuracao = parseInt(diaMatch[1], 10);
      }
      isAjusteOrcamentoRui = true;
    }
  }
}

const isComandoRui = isAprovacaoRui || isAjusteOrcamentoRui;

const pediuAudio = (
  norm.isAudio ||
  textoLower.includes('mande um áudio') ||
  textoLower.includes('mande um audio') ||
  textoLower.includes('manda um áudio') ||
  textoLower.includes('manda um audio') ||
  textoLower.includes('mandei um áudio') ||
  textoLower.includes('mandei um audio') ||
  textoLower.includes('manda audio') ||
  textoLower.includes('manda áudio') ||
  textoLower.includes('grava um áudio') ||
  textoLower.includes('grava um audio') ||
  textoLower.includes('audio seu') ||
  textoLower.includes('áudio seu')
);

const temMidia = Boolean(norm.isFoto || norm.isPdf);

return [{
  json: {
    ...norm,
    textoRecebido: textoConsolidado,
    pedeHumano: pedeHumano,
    pediuAudio: pediuAudio,
    temMidia: temMidia,
    isAprovacaoRui: isAprovacaoRui,
    isAjusteOrcamentoRui: isAjusteOrcamentoRui,
    novoValorDiario: novoValorDiario,
    diasDuracao: diasDuracao,
    isComandoRui: isComandoRui
  }
}];

