const evoMedia = $input.first() ? $input.first().json : {};
const prev = $('Consolidar Mensagens e Filtrar Vencedor').item.json;

let mediaBase64 = null;
let mediaMimetype = null;
let isFotoReal = false;
let isPdfReal = false;

if (evoMedia && evoMedia.base64) {
  mediaBase64 = evoMedia.base64;
  mediaMimetype = evoMedia.mimetype || 'image/jpeg';
  if (mediaMimetype.startsWith('image/')) {
    isFotoReal = true;
  } else if (mediaMimetype.includes('pdf')) {
    isPdfReal = true;
  }
}

return [{
  json: {
    ...prev,
    mediaBase64: mediaBase64,
    mediaMimetype: mediaMimetype,
    isFotoReal: isFotoReal,
    isPdfReal: isPdfReal,
    fileName: evoMedia.fileName || ''
  }
}];

const prev = $input.first() ? $input.first().json : {};
const remoteJid = prev.remoteJid || '';
const number = prev.number || '';
const userText = (prev.text || prev.body || prev.mensagem || '').trim();
const txtLow = userText.toLowerCase();

const supabaseUrl = "https://qkopgftfrfftoyndhhfj.supabase.co";
const supabaseKey = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFrb3BnZnRmcmZmdG95bmRoaGZqIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MTgwMTU4MywiZXhwIjoyMTA3Mzc3NTgzfQ.S_RRdnI6SZTVR1UH7jryDVHf316YmnMOVEBuoedyKv8";

// 1. Buscar histórico de conversas
let histData = [];
try {
  let url = `${supabaseUrl}/rest/v1/leads_conversas?select=historico_mensagens,etapa_funil,push_name`;
  if (remoteJid && number) {
    url += `&or=(remote_jid.eq.${encodeURIComponent(remoteJid)},telefone.eq.${encodeURIComponent(number)})`;
  } else if (remoteJid) {
    url += `&remote_jid=eq.${encodeURIComponent(remoteJid)}`;
  } else if (number) {
    url += `&telefone=eq.${encodeURIComponent(number)}`;
  }

  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` },
    json: true
  });
  if (Array.isArray(res)) histData = res;
} catch (e) {}

// 2. Buscar Ficha Clínica do Aluno
let fichaAluno = null;
const cleanNum = number.replace(/\D/g, '');
const last8 = cleanNum.slice(-8);

try {
  const rFicha = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/fichas_alunos?select=*`,
    headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` },
    json: true
  });
  if (Array.isArray(rFicha)) {
    fichaAluno = rFicha.find(f => {
      const fNum = (f.telefone || '').replace(/\D/g, '');
      const fJid = (f.remote_jid || '').replace(/\D/g, '');
      return (last8 && (fNum.endsWith(last8) || fJid.includes(last8))) || (remoteJid && f.remote_jid === remoteJid);
    });
  }
} catch (e) {}

// 3. Processamento de LGPD ('CONCORDO') e Parser Clínico
const patchFicha = {};
const agoraIso = new Date().toISOString();

// A. Detecção de 'CONCORDO' / Consentimento LGPD
const termosConcordo = ["concordo", "ciente", "autorizo", "aceito", "sim", "com certeza", "pode", "ok", "claro", "bora", "fechado"];
const ehConcordo = termosConcordo.some(t => txtLow.includes(t)) || prev.isEvandro;

if (ehConcordo && (!fichaAluno || !fichaAluno.consentimento_lgpd)) {
  patchFicha.consentimento_lgpd = true;
  patchFicha.data_consentimento_lgpd = agoraIso;
  patchFicha.termo_lgpd_versao = 'v2.0_lgpd';
  patchFicha.status_acompanhamento = 'ativo';
}

// B. Extração de Idade
const matchIdade = txtLow.match(/\b(?:tenho|minha idade [eé]|idade[:\s]*)?(\d{1,2})\s*(?:anos|ano)?\b/);
if (matchIdade) {
  const idVal = parseInt(matchIdade[1], 10);
  if (idVal >= 12 && idVal <= 95) patchFicha.idade = idVal;
}

// C. Extração de Peso
const matchPeso = txtLow.match(/\b(?:peso|pesando|estou com|to com|de)?\s*(\d{2,3}(?:[.,]\d{1,2})?)\s*(?:kg|quilos|kilos)\b/) ||
                  txtLow.match(/\bpeso[:\s]*(\d{2,3}(?:[.,]\d{1,2})?)\b/);
if (matchPeso) {
  const pVal = parseFloat(matchPeso[1].replace(',', '.'));
  if (pVal >= 35 && pVal <= 250) {
    patchFicha.metas_nutricionais = {
      ...(fichaAluno?.metas_nutricionais || {}),
      peso: pVal
    };
  }
}

// D. Extração de Altura
const matchAltura = txtLow.match(/\b(?:altura[:\s]*)?(1[.,]\d{2})\s*(?:m|metros)?\b/) ||
                    txtLow.match(/\b(?:altura[:\s]*)?(1\d{2})\s*(?:cm)?\b/);
if (matchAltura) {
  let altCm = parseFloat(matchAltura[1].replace(',', '.'));
  if (altCm < 3) altCm = Math.round(altCm * 100);
  if (altCm >= 120 && altCm <= 230) {
    patchFicha.metas_nutricionais = {
      ...(patchFicha.metas_nutricionais || fichaAluno?.metas_nutricionais || {}),
      altura_cm: altCm
    };
  }
}

// E. Local de Treino
if (txtLow.includes('academia') || txtLow.includes('gym')) {
  patchFicha.local_treino = 'academia';
} else if (txtLow.includes('casa') || txtLow.includes('em casa') || txtLow.includes('quarto') || txtLow.includes('sala')) {
  patchFicha.local_treino = 'casa';
} else if (txtLow.includes('condominio') || txtLow.includes('condomínio')) {
  patchFicha.local_treino = 'condomínio';
} else if (txtLow.includes('ar livre') || txtLow.includes('parque') || txtLow.includes('rua') || txtLow.includes('praia')) {
  patchFicha.local_treino = 'ar livre';
}

// F. Dores Articulares e Restrições
const doresDetectadas = [];
if (txtLow.includes('joelho')) doresDetectadas.push('Sensibilidade/Dor no joelho (evitar impacto e agachamento profundo)');
if (txtLow.includes('coluna') || txtLow.includes('lombar') || txtLow.includes('costas') || txtLow.includes('hernia') || txtLow.includes('hérnia')) doresDetectadas.push('Coluna/Lombar (preservar postura, sem sobrecarga axial)');
if (txtLow.includes('ombro') || txtLow.includes('manguito')) doresDetectadas.push('Ombro/Manguito (cuidado com desenvolvimento e abdução)');
if (txtLow.includes('pressao') || txtLow.includes('pressão') || txtLow.includes('hipertens')) doresDetectadas.push('Hipertensão (controle de esforço contínuo e sem manobra de Valsalva)');
if (txtLow.includes('labirintite')) doresDetectadas.push('Labirintite (evitar trocas bruscas de nível de cabeça)');
if (doresDetectadas.length > 0) {
  patchFicha.restricoes_saude = doresDetectadas.join('; ');
}

// G. Objetivo
if (txtLow.includes('hipertrofia') || txtLow.includes('massa muscular') || txtLow.includes('ganhar musculo') || txtLow.includes('crescer')) {
  patchFicha.objetivo = 'Hipertrofia e Ganho de Massa Magra';
} else if (txtLow.includes('secar') || txtLow.includes('perder barriga') || txtLow.includes('emagrecer') || txtLow.includes('queimar gordura')) {
  patchFicha.objetivo = 'Secar Barriga, Emagrecimento e Definição';
} else if (txtLow.includes('definir') || txtLow.includes('tonificar')) {
  patchFicha.objetivo = 'Definição Muscular e Tônus Corporal';
} else if (txtLow.includes('saude') || txtLow.includes('saúde') || txtLow.includes('longevidade') || txtLow.includes('disposição')) {
  patchFicha.objetivo = 'Saúde, Longevidade e Disposição';
}

// H. Esportista / Nível Atleta
if (txtLow.includes('corrida') || txtLow.includes('maratona') || txtLow.includes('corredor') || txtLow.includes('atleta') || txtLow.includes('compet')) {
  patchFicha.experiencia_nivel = 'atleta_esportista';
}

// I. Gênero / Identidade Personalizada
if (txtLow.includes('sou mulher') || txtLow.includes('feminino') || txtLow.includes('uma mulher')) {
  patchFicha.genero = 'mulher';
} else if (txtLow.includes('sou homem') || txtLow.includes('masculino') || txtLow.includes('um homem')) {
  patchFicha.genero = 'homem';
} else if (txtLow.includes('me chame de') || txtLow.includes('prefiro que me chame') || txtLow.includes('meus pronomes')) {
  patchFicha.genero = userText.slice(0, 50);
}

// 4. Salvar no Supabase se houver alterações
if (Object.keys(patchFicha).length > 0) {
  try {
    if (fichaAluno && fichaAluno.id) {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: `${supabaseUrl}/rest/v1/fichas_alunos?id=eq.${fichaAluno.id}`,
        headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' },
        body: { ...patchFicha, updated_at: agoraIso },
        json: true
      });
      fichaAluno = { ...fichaAluno, ...patchFicha };
    } else if (remoteJid || number) {
      const createdFicha = await this.helpers.httpRequest({
        method: 'POST',
        url: `${supabaseUrl}/rest/v1/fichas_alunos`,
        headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
        body: {
          remote_jid: remoteJid || `${number}@s.whatsapp.net`,
          telefone: number,
          nome: prev.pushName || 'Aluno(a) VIP',
          nome_aluno: prev.pushName || 'Aluno(a) VIP',
          consentimento_lgpd: Boolean(patchFicha.consentimento_lgpd || prev.isEvandro),
          data_consentimento_lgpd: patchFicha.data_consentimento_lgpd || (prev.isEvandro ? agoraIso : null),
          termo_lgpd_versao: 'v2.0_lgpd',
          status_acompanhamento: 'ativo',
          ...patchFicha
        },
        json: true
      });
      if (Array.isArray(createdFicha) && createdFicha[0]) {
        fichaAluno = createdFicha[0];
      }
    }
  } catch (e) {}
}

return [{
  json: {
    ...prev,
    ficha_aluno: fichaAluno,
    confirmou_lgpd_agora: Boolean(ehConcordo && patchFicha.consentimento_lgpd),
    historico_mensagens: (histData[0] && Array.isArray(histData[0].historico_mensagens)) ? histData[0].historico_mensagens : [],
    etapa_funil: histData[0]?.etapa_funil || 'novo',
    push_name_salvo: histData[0]?.push_name || ''
  }
}];

function devePesquisarNaWeb(texto) {
  if (!texto) return false;
  let t = texto.trim().toLowerCase();

  t = t.replace(/[!?,;.]+/g, ' ').replace(/\s+/g, ' ').trim();

  const tokensCasuais = new Set([
    'ok', 'tudo', 'bem', 'bom', 'td', 'certo', 'cima', 'beleza', 'blz', 'tranquilo', 
    'como', 'vai', 'voce', 'você', 'esta', 'está', 'e', 'ai', 'aí', 'opa', 'oi', 
    'ola', 'olá', 'bom', 'dia', 'boa', 'tarde', 'noite', 'valeu', 'obrigado', 
    'obrigada', 'combinado', 'fechado', 'sim', 'ta', 'tá', 'show', 'top', 'tmj', 
    'marcao', 'marcão', 'fala', 'irmão', 'irmao', 'parceiro', 'campeão', 'campeao'
  ]);

  const palavras = t.split(' ').filter(w => w.length > 0);
  const todasSaoCasuais = palavras.length > 0 && palavras.every(w => tokensCasuais.has(w));
  if (todasSaoCasuais) return false;

  if (/^(treinei|treino pago|t[aá] pago|fui treinar|acabei o treino|hoje tem|cansei|pesando|estou com|tenho \d+|concordo|fechado)/i.test(t)) {
    return false;
