const item = $input.first().json;
const rawContent = (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content) ? item.choices[0].message.content.trim() : '';
const info = $('Montar Prompt com Memória e Visão').item.json;

let temDespacho = false;
let despacho = null;
let temLembrete = false;
let lembrete = null;
let textoLimpo = rawContent;

const userMsg = String(info.textoRecebido || '').trim();
const userMsgLower = userMsg.toLowerCase();

// =========================================================================
// 1. CAPTURA UNIVERSAL DE ANAMNESE & LGPD (PARA ALUNOS VIP, LEADS E CHEFE)
// =========================================================================
const concordouLgpd = (
  userMsgLower === 'concordo' ||
  userMsgLower === 'concordo.' ||
  userMsgLower.includes('concordo') ||
  userMsgLower.includes('aceito') ||
  userMsgLower.includes('ciente') ||
  userMsgLower === 'sim' ||
  userMsgLower === 'sim, concordo'
);

let pesoDetectado = null;
const mPeso = userMsgLower.match(/(?:peso|estou com|pesando|balan[cç]a|deu)?\s*(\d{2,3}(?:[.,]\d+)?)\s*(?:kg|quilos|kilos)?/i);
if (mPeso) {
  const pVal = parseFloat(mPeso[1].replace(',', '.'));
  if (pVal >= 35 && pVal <= 250) pesoDetectado = pVal;
}

let alturaDetectada = null;
const mAlt = userMsgLower.match(/(?:tenho|me[cç]o|altura)?\s*(1[.,]\d{2})\s*(?:m|metros)?/i) || userMsgLower.match(/\b(1\d{2})\s*cm\b/i);
if (mAlt) {
  let aVal = parseFloat(mAlt[1].replace(',', '.'));
  if (aVal < 3.0) aVal = Math.round(aVal * 100);
  if (aVal >= 120 && aVal <= 230) alturaDetectada = aVal;
}

let idadeDetectada = null;
const mIdade = userMsgLower.match(/\b(\d{1,2})\s*anos\b/i);
if (mIdade) {
  const idVal = parseInt(mIdade[1], 10);
  if (idVal >= 12 && idVal <= 100) idadeDetectada = idVal;
}

let localDetectado = null;
if (userMsgLower.includes('em casa') || userMsgLower.includes('na casa') || userMsgLower.includes('treino em casa') || userMsgLower.includes('casa')) {
  localDetectado = 'casa';
} else if (userMsgLower.includes('academia') || userMsgLower.includes('musculação') || userMsgLower.includes('aparelho')) {
  localDetectado = 'academia';
}

let restricoesDetectadas = null;
if (userMsgLower.includes('joelho') || userMsgLower.includes('coluna') || userMsgLower.includes('lombar') || userMsgLower.includes('ombro') || userMsgLower.includes('hérnia') || userMsgLower.includes('hernia') || userMsgLower.includes('menisco')) {
  const dores = [];
  if (userMsgLower.includes('joelho')) dores.push('dor/lesão no joelho');
  if (userMsgLower.includes('coluna') || userMsgLower.includes('lombar')) dores.push('dor na coluna/lombar');
  if (userMsgLower.includes('ombro')) dores.push('dor no ombro');
  if (userMsgLower.includes('hérnia') || userMsgLower.includes('hernia')) dores.push('hérnia de disco');
  restricoesDetectadas = dores.join(', ');
} else if (userMsgLower.includes('nenhuma') || userMsgLower.includes('sem dor') || userMsgLower.includes('tudo certo') || userMsgLower.includes('tudo ok')) {
  restricoesDetectadas = 'Nenhuma dor ou lesão reportada';
}

if (concordouLgpd || pesoDetectado || alturaDetectada || idadeDetectada || localDetectado || restricoesDetectadas) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://admin.marcaopersonal.com/api/vip/salvar-anamnese',
      body: {
        telefone: info.number,
        remote_jid: info.remoteJid,
        nome: info.pushName || info.nomeValido || (info.isEvandro ? 'Evandro Gallina' : 'Aluno'),
        peso: pesoDetectado,
        altura_cm: alturaDetectada,
        idade: idadeDetectada,
        local_treino: localDetectado,
        restricoes: restricoesDetectadas,
        consentimento_lgpd: concordouLgpd
      },
      json: true
    });
  } catch(e) {}
}

// Se o Chefe confirmou LGPD explicitamente, garante resposta comemorativa caso o LLM não tenha respondido
if (info.isEvandro && concordouLgpd && (!rawContent || rawContent.length < 15)) {
  textoLimpo = "Termo LGPD e responsabilidade confirmados com sucesso, meu chefe! Ficha 100% liberada! Bora montar seu protocolo e sua dieta de alta performance! Me diz o que você quer priorizar hoje! 💪🦁";
}

// =========================================================================
// 2. PROCESSAMENTO EXCLUSIVO DE COMANDOS DO CHEFE EVANDRO
// =========================================================================
if (info.isEvandro) {
  // A. Extração do histórico apenas das mensagens do próprio Chefe (para contexto imediato)
  const histList = info.historicoPrevio || info.historicoSalvar || info.historico || info.messages || [];
  const histTexts = [];
  for (const h of histList.slice(-6)) {
    if (typeof h === 'string') {
      histTexts.push(h);
    } else if (h && typeof h === 'object') {
      if (typeof h.content === 'string') histTexts.push(h.content);
      else if (Array.isArray(h.content)) {
        for (const sub of h.content) {
          if (sub && sub.text) histTexts.push(sub.text);
        }
      }
      if (h.texto) histTexts.push(h.texto);
      if (h.mensagem_texto) histTexts.push(h.mensagem_texto);
    }
  }

  // B. Parser do bloco LLM <<<DESPACHO_TERCEIRO>>>
  let despachoLlm = null;
  const matchTag = rawContent.match(/<<<DESPACHO_TERCEIRO>>>([\s\S]*?)(?:<<<FIM_DESPACHO>>>|$)/i);
  if (matchTag) {
    try {
      let jsonStr = matchTag[1].replace(/```json/gi, '').replace(/```/g, '').trim();
      despachoLlm = JSON.parse(jsonStr);
    } catch (e) {
      const mNum = matchTag[1].match(/"numero_destino":\s*"([^"]+)"/);
      const mNome = matchTag[1].match(/"nome_destino":\s*"([^"]+)"/);
      const mTipo = matchTag[1].match(/"tipo":\s*"([^"]+)"/);
      const mMsg = matchTag[1].match(/"mensagem_terceiro":\s*"([^"]+)"/);
      if (mNum || mMsg) {
        despachoLlm = {
          executar: true,
          numero_destino: mNum ? mNum[1] : '',
          nome_destino: mNome ? mNome[1] : 'Contato',
          tipo: mTipo ? mTipo[1] : 'audio',
          mensagem_terceiro: mMsg ? mMsg[1] : ''
        };
      }
    }
  }

  // C. GUARDRAILS ABSOLUTOS DE DESPACHO:
  // Se a mensagem for LGPD, Dieta, Treino, Ficha, Saudação, CFO ou IG, NUNCA É DESPACHO!
  const ehLgpdChefe = concordouLgpd || userMsgLower.includes('lgpd') || userMsgLower.includes('termo');
  const ehDietaOuTreinoChefe = /\b(dieta|treino|ficha|exercicio|exercício|cardapio|cardápio|alimentacao|alimentação|refeicao|refeição|massa|hipertrofia|secar|peso|shape|protocolo)\b/i.test(userMsgLower);
  const ehConversaCasualChefe = /^(oi|ol[aá]|bom dia|boa tarde|boa noite|tudo bem|como vai|e a[ií]|valeu|show|top|ok)[\.!\s]*$/i.test(userMsgLower);
  const ehComandoCfo = userMsgLower.includes('venda') || userMsgLower.includes('faturam') || userMsgLower.includes('financeir') || userMsgLower.includes('quanto vend') || userMsgLower.includes('lucro') || userMsgLower.includes('cfo');
  const ehComandoIg = userMsgLower.includes('post') || userMsgLower.includes('instagram') || userMsgLower.includes('stories') || userMsgLower.includes('feed') || userMsgLower.includes('publica');
  const ehComandoStatus = userMsgLower.includes('diagnostico') || userMsgLower.includes('status') || userMsgLower.includes('sistema') || userMsgLower.includes('ta funcionando') || userMsgLower.includes('está funcionando');

  // Só pode ser despacho se NÃO for nenhum dos casos acima E houver solicitação explícita NO TURNO ATUAL!
  const podeSerDespacho = !ehLgpdChefe && !ehDietaOuTreinoChefe && !ehConversaCasualChefe && !ehComandoCfo && !ehComandoIg && !ehComandoStatus;

  if (podeSerDespacho) {
    const temContatoNoTurno = userMsg.includes('[Contato compartilhado:');
    const temComandoEnvioNoTurno = /\b(manda|mande|envia|envie|grava|grave|fala com|avisa|recado pro|piada pro|áudio pro|audio pro|manda pra|mande pra|envia pra|envie pra)\b/i.test(userMsgLower);

    const pediuDespacho = Boolean(
      (despachoLlm && despachoLlm.executar === true) ||
      temContatoNoTurno ||
      temComandoEnvioNoTurno
    );

    if (pediuDespacho) {
      let targetNumber = '';
      let targetName = '';

