      if (mContato) {
        targetName = mContato[1].trim();
        targetNumber = mContato[2].replace(/\D/g, '');
      }

      // 2. Destinatários nomeados explicitamente pelo Chefe
      if (!targetNumber) {
        if (userMsgLower.includes('deivyd') || userMsgLower.includes('david')) {
          targetNumber = '553288010246'; targetName = 'Deivyd Prefeitura';
        } else if (userMsgLower.includes('gregorio') || userMsgLower.includes('gregório')) {
          targetNumber = '553291159389'; targetName = 'Gregório';
        } else if (userMsgLower.includes('bryan')) {
          targetNumber = '553298587100'; targetName = 'Bryan';
        } else if (userMsgLower.includes('adilio') || userMsgLower.includes('adílio')) {
          targetNumber = '553299773744'; targetName = 'Adílio';
        } else if (userMsgLower.includes('eva')) {
          targetNumber = '5532988273367'; targetName = 'Eva Maria';
        }
      }

      // 3. Destinatário retornado pelo bloco do LLM
      if (!targetNumber && despachoLlm && despachoLlm.numero_destino) {
        targetNumber = String(despachoLlm.numero_destino).replace(/\D/g, '');
        if (!targetName && despachoLlm.nome_destino) targetName = despachoLlm.nome_destino;
      }

      // 4. Só busca contato no histórico se o Chefe disser explicitamente "manda pra ele / manda pra ela / pro contato"
